    private static List<string> SplitSections(string html)
    {
        var sections = new List<string>();
        var idx = 0;
        while (idx >= 0)
        {
            var start = html.IndexOf("<section class=\"page\"", idx, StringComparison.Ordinal);
            if (start < 0) break;
            var end = html.IndexOf("</section>", start, StringComparison.Ordinal);
            if (end < 0) break;
            sections.Add(html.Substring(start, end - start));
            idx = end + "</section>".Length;
        }
        return sections;
    }

    /// <summary>
    /// 從 PDF 原始位元組提取所有可見文字。
    /// Chromium 生成的 PDF 使用 UTF-16BE 或 CIDFont 編碼，簡易方式是讀取 content streams 中的字串。
    /// 此方法搜尋 BT/ET 區塊中的 Tj/TJ 操作符並提取文字。
    /// 由於 CJK 字符以 CIDFont 嵌入，PDF 文字串解析需解碼，這裡採用字串搜尋模板關鍵字更可靠。
    /// </summary>
    private static string ExtractPdfAllText(byte[] pdfBytes)
    {
        // 策略：把整個 PDF 當 Latin-1 讀，搜尋 Tf 指令後的字串文字
        // Chromium 生成的 PDF 中中文字以 hex 字串或 glyph id 儲存，原始文字搜尋不可行
        // 改用：解碼 PDF 中所有小括號內容 (literal strings) 以及角括號內容 (hex strings)
        var latin1 = Encoding.Latin1.GetString(pdfBytes);

        var sb = new StringBuilder();

        // 提取 literal strings: (...) — 但 Chromium PDF 中文本以 hex strings 居多
        var literalMatches = Regex.Matches(latin1, @"\(([^)\\]*(?:\\.[^)\\]*)*)\)");
        foreach (Match m in literalMatches)
        {
            var text = Unescape(m.Groups[1].Value);
            sb.Append(text).Append(' ');
        }

        // 提取 hex strings: <hex...>
        var hexMatches = Regex.Matches(latin1, @"<([0-9A-Fa-f\s]+)>");
        foreach (Match m in hexMatches)
        {
            var hex = Regex.Replace(m.Groups[1].Value, @"\s", "");
            if (hex.Length % 2 != 0) continue;
            if (hex.Length < 4) continue;  // 跳過太短的（如色值）
            var decoded = HexToUtf16String(hex);
            if (!string.IsNullOrEmpty(decoded)) sb.Append(decoded).Append(' ');
        }

        return sb.ToString();
    }

    private static string HexToUtf16String(string hex)
    {
        try
        {
            var bytes = new byte[hex.Length / 2];
            for (int i = 0; i < bytes.Length; i++)
                bytes[i] = Convert.ToByte(hex.Substring(i * 2, 2), 16);
            // 嘗試 UTF-16BE 解碼（Chromium CJK PDF 常用）
            var text = Encoding.BigEndianUnicode.GetString(bytes);
            // 過濾非可見字元
            var filtered = new string(text.Where(c => !char.IsControl(c) || c == '\n').ToArray());
            return filtered;
        }
        catch { return string.Empty; }
    }

    private static string Unescape(string s)
    {
        return s.Replace("\\n", "\n").Replace("\\r", "\r").Replace("\\t", "\t")
                .Replace("\\(", "(").Replace("\\)", ")").Replace("\\\\", "\\");
    }

    /// <summary>
    /// 從 PDF 原始位元組解析頁數。
    /// 搜尋 /Count N，取最大值（通常就是根 Pages 節點的總頁數）。
    /// </summary>
    private static int ExtractPdfPageCount(byte[] pdfBytes)
    {
        var latin1 = Encoding.Latin1.GetString(pdfBytes);

        // 取所有 /Count N，取最大值作為總頁數
        var allCounts = Regex.Matches(latin1, @"/Count\s+(\d+)");
        int max = 0;
        foreach (Match mm in allCounts)
        {
            if (int.TryParse(mm.Groups[1].Value, out var v) && v > max) max = v;
        }
        return max;
    }
